fn solve(m:i64,e:i64)->i64 {
 let mut x:i64=add(m,e); x=select(sgt(x,843314857i64),843314857i64,x);
 let mut lo:i64=0i64; let mut hi:i64=843314857i64; let mut tick:i64=0i64;
 while slt(tick,3i64) {
  let y:i64=select(sgt(x,421657428i64),sub(843314857i64,x),x);
  let z:i64=ashr(mul(y,y),28i64);
  let sn:i64=ashr(mul(y,add(268435456i64,ashr(mul(add(-44739243i64,ashr(mul(add(2236962i64,ashr(mul(add(-53261i64,ashr(mul(add(740i64,ashr(mul(-7i64,z),28i64)),z),28i64)),z),28i64)),z),28i64)),z),28i64))),28i64);
  let cp:i64=add(268435456i64,ashr(mul(add(-134217728i64,ashr(mul(add(11184811i64,ashr(mul(add(-372827i64,ashr(mul(add(6658i64,ashr(mul(-74i64,z),28i64)),z),28i64)),z),28i64)),z),28i64)),z),28i64)); let cs:i64=select(sgt(x,421657428i64),sub(0i64,cp),cp);
  let es:i64=ashr(mul(e,sn),28i64); let f:i64=sub(sub(x,m),es);
  let af:i64=select(slt(f,0i64),sub(0i64,f),f);
  if slt(af,256i64) { break; }
  if sgt(f,0i64) { hi=x; } else { lo=x; }
  let d:i64=sub(268435456i64,ashr(mul(e,cs),28i64)); let mut step:i64=0i64;
  if slt(tick,0i64) { step=sdiv(sdiv(mul(f,268435456i64),d),2i64); } else { let n:i64=sdiv(mul(f,268435456i64),d); let h:i64=sub(d,sdiv(ashr(mul(es,n),28i64),2i64)); if sgt(h,26843i64) { step=sdiv(mul(f,268435456i64),h); } else { step=n; } }

  let mut next:i64=sub(x,step); 
  x=select(slt(next,0i64),0i64,select(sgt(next,843314857i64),843314857i64,next));
  tick=add(tick,1i64);
 }
 return x;
}
